export type SchemaValidatorStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface SchemaValidatorEvent {{
  kind: 'rebalance' | 'validate' | 'error';
  duration: string;
  timestamp: number;
}}

export type RebalanceEvent = Extract<SchemaValidatorEvent, {{ kind: 'rebalance' }}>;
export type ErrorEvent = Extract<SchemaValidatorEvent, {{ kind: 'error' }}>;

export interface SchemaValidatorConfig {{
  readonly duration: string;
  readonly ttl: number;
  readonly concurrency?: Record<string, unknown>;
}}

export type PartialSchemaValidator = Partial<SchemaValidatorConfig> & Pick<SchemaValidatorConfig, 'duration'>;

export function isSchemaValidatorEvent(e: unknown): e is SchemaValidatorEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as SchemaValidatorEvent).duration === 'string'
  );
}}

export function assertSchemaValidatorStatus(s: string): asserts s is SchemaValidatorStatus {{
  const valid: SchemaValidatorStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as SchemaValidatorStatus)) {{
    throw new Error(`authentication failed: ${{s}}`);
  }}
}}


