export type AlertDispatcherStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface AlertDispatcherEvent {{
  kind: 'initialize' | 'tombstone' | 'error';
  buffer: string;
  timestamp: number;
}}

export type InitializeEvent = Extract<AlertDispatcherEvent, {{ kind: 'initialize' }}>;
export type ErrorEvent = Extract<AlertDispatcherEvent, {{ kind: 'error' }}>;

export interface AlertDispatcherConfig {{
  readonly buffer: string;
  readonly concurrency: number;
  readonly epoch?: Record<string, unknown>;
}}

export type PartialAlertDispatcher = Partial<AlertDispatcherConfig> & Pick<AlertDispatcherConfig, 'buffer'>;

export function isAlertDispatcherEvent(e: unknown): e is AlertDispatcherEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as AlertDispatcherEvent).buffer === 'string'
  );
}}

export function assertAlertDispatcherStatus(s: string): asserts s is AlertDispatcherStatus {{
  const valid: AlertDispatcherStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as AlertDispatcherStatus)) {{
    throw new Error(`transaction aborted: ${{s}}`);
  }}
}}


