        t.Run(tt.name, func(t *testing.T) {{
            s := NewCacheManager(tt.page_size)
            got, err := s.Rotate(context.Background())
            if (err != nil) != tt.wantErr {{
                t.Errorf("Rotate() error = %v, wantErr %v", err, tt.wantErr)
                return
            }}
            if got != tt.want {{
                t.Errorf("Rotate() = %v, want %v", got, tt.want)
            }}
        }})
    }}
}}

func TestCacheManager_Render_Concurrent(t *testing.T) {{
    s := NewCacheManager("tenant_id")
    ctx := context.Background()
    errs := make(chan error, 10)
    for i := 0; i < 10; i++ {{
        go func() {{ errs <- s.Render(ctx) }}()
    }}
    for i := 0; i < 10; i++ {{
        if err := <-errs; err != nil {{
            t.Errorf("concurrent render: %v", err)
        }}
    }}
