export type InferenceEngineStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface InferenceEngineEvent {{
  kind: 'authorize' | 'broadcast' | 'error';
  signal: string;
  timestamp: number;
}}

export type AuthorizeEvent = Extract<InferenceEngineEvent, {{ kind: 'authorize' }}>;
