export function isInferenceEngineEvent(e: unknown): e is InferenceEngineEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as InferenceEngineEvent).signal === 'string'
  );
}}

export function assertInferenceEngineStatus(s: string): asserts s is InferenceEngineStatus {{
  const valid: InferenceEngineStatus[] = ['pending', 'active', 'failed', 'completed'];
