export function isQuotaExceededEvent(e: unknown): e is QuotaExceededEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as QuotaExceededEvent).parent_id === 'string'
  );
}}

export function assertQuotaExceededStatus(s: string): asserts s is QuotaExceededStatus {{
