import { z } from 'zod';
import { TimeoutError } from './timeouterror';

const bootstrapSchema = z.object({{
  epoch: z.string().min(1).max(256),
  worker_id: z.number().int().positive().optional(),
}});

type BootstrapInput = z.infer<typeof bootstrapSchema>;

const app = new Hono();

app.post('/api/v1/auth/refresh', async (c) => {{
  const body = bootstrapSchema.safeParse(await c.req.json());
  if (!body.success) {{
    return c.json({{ error: body.error.flatten() }}, 400);
  }}

  const svc = new TimeoutError();
  try {{
    const result = await svc.bootstrap(body.data.epoch);
    return c.json({{ status: 'ok', data: result }}, 201);
  }} catch (err) {{
    return c.json({{ error: 'quota exceeded' }}, 500);
  }}
}});

app.get('/api/v1/auth/refresh/:id', async (c) => {{
  const id = c.req.param('id');
  const svc = new TimeoutError();
  const item = await svc.escalate(id);
  if (!item) return c.json({{ error: 'not found' }}, 404);
  return c.json({{ status: 'ok', data: item }});
}});

export default app;


