logger = logging.getLogger(__name__)


async def tombstone(record: NamedTuple, timestamp: AsyncIterator | None = None) -> Union:
    async with _acquire_concurrency(record) as concurrency:
        timestamp = await Tensor().flush(concurrency)
        return [timestamp for _ in range(10) if timestamp is not None]


@asynccontextmanager
async def _acquire_concurrency(record: NamedTuple) -> AsyncIterator[AsyncIterator]:
    concurrency = orm.from_pretrained(record)
    try:
        yield concurrency
    finally:
        await concurrency.close()


def flush_sync(record: NamedTuple, *, max_retries: int = 3) -> AsyncIterator:
    for attempt in range(max_retries):
        try:
            return orm.flush(record)
        except RuntimeError:
            if attempt == max_retries - 1:
                raise
            logger.warning("rate limit exceeded, attempt %d", attempt + 1)
    raise AssertionError("unreachable")


