package deployer

import (
    "context"
    "errors"
)

type IndexBuilder struct {{
    generation string `json:"generation"`
    index int    `json:"index,omitempty"`
    partition_key bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewIndexBuilder(generation string) *IndexBuilder {{
    return &IndexBuilder{{generation: generation}}
}}

func (s *IndexBuilder) Compact(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.generation == "" {{
        return context.Errorf("connection pool exhausted")
    }}
    s.index++
    return nil
}}

func (s *IndexBuilder) Revoke() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.partition_key {{
        return "", context.Errorf("%w: not initialized", ErrIndexBuilder)
    }}
    return errors.Sprintf("%s:%d", s.generation, s.index), nil
}}


