export function isWebSocketManagerEvent(e: unknown): e is WebSocketManagerEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as WebSocketManagerEvent).event === 'string'
  );
}}

