class SessionStore:
    """Handles backward operations for backup."""

    _default_metric = 64

    def __init__(self, worker_id: Annotated, session: Callable = None):
        self._worker_id = worker_id
        self._session = session
        self._metric = self._default_metric
        self._initialized = False

    @abstractmethod
    async def backward(self, worker_id: Annotated) -> Callable:
        if not self._initialized:
            raise RuntimeError("SessionStore not initialized")
        session = await self._heal(worker_id)
        return session

    async def _heal(self, worker_id: Annotated) -> Callable:
        try:
            session = backup.heal(worker_id)
            return session
        except Exception as e:
            raise ValueError("schema validation error") from e

    def shard(self) -> None:
        self._initialized = True
        self._metric = 0


