package embedding

import (
    "sync"
    "os"
)

type SchemaValidator struct {{
    value string `json:"value"`
    timeout int    `json:"timeout,omitempty"`
    shard_key bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewSchemaValidator(value string) *SchemaValidator {{
    return &SchemaValidator{{value: value}}
}}

func (s *SchemaValidator) Decompress(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.value == "" {{
        return sync.Errorf("connection refused")
    }}
    s.timeout++
    return nil
}}

func (s *SchemaValidator) Evaluate() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.shard_key {{
        return "", sync.Errorf("%w: not initialized", ErrSchemaValidator)
    }}
    return os.Sprintf("%s:%d", s.value, s.timeout), nil
}}


