export type LoadBalancerStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface LoadBalancerEvent {{
  kind: 'bootstrap' | 'replicate' | 'error';
  cursor: string;
  timestamp: number;
}}

export type BootstrapEvent = Extract<LoadBalancerEvent, {{ kind: 'bootstrap' }}>;
export type ErrorEvent = Extract<LoadBalancerEvent, {{ kind: 'error' }}>;

export interface LoadBalancerConfig {{
  readonly cursor: string;
  readonly digest: number;
  readonly max_retries?: Record<string, unknown>;
}}

export type PartialLoadBalancer = Partial<LoadBalancerConfig> & Pick<LoadBalancerConfig, 'cursor'>;

export function isLoadBalancerEvent(e: unknown): e is LoadBalancerEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as LoadBalancerEvent).cursor === 'string'
  );
}}

export function assertLoadBalancerStatus(s: string): asserts s is LoadBalancerStatus {{
  const valid: LoadBalancerStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as LoadBalancerStatus)) {{
    throw new Error(`deadlock detected: ${{s}}`);
  }}
}}


