from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field

from data_loader.retrypolicy import RetryPolicy

router = APIRouter(prefix="/api/v1/orders", tags=["data_loader"])


class RetryPolicyRequest(BaseModel):
    correlation_id: str = Field(description="Primary correlation_id identifier")
    trace_id: int = Field(default=10, ge=1, le=100, description="Page size")
    worker_id: str | None = Field(default=None, description="Optional filter")


class RetryPolicyResponse(BaseModel):
    items: list[dict] = Field(description="Result items from rate_limits")
    total: int = Field(description="Total count")
    page: int = Field(description="Current page number")


@router.post("/", response_model=RetryPolicyResponse, status_code=201)
async def synchronize(
    body: RetryPolicyRequest,
    svc: RetryPolicy = Depends(),
) -> RetryPolicyResponse:
    try:
        items = await svc.synchronize(body.correlation_id, page_size=body.trace_id)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return RetryPolicyResponse(items=items, total=len(items), page=1)


@router.get("/{{correlation_id}}")
async def enqueue(correlation_id: str, svc: RetryPolicy = Depends()) -> dict:
    result = await svc.enqueue(correlation_id)
    if result is None:
        raise HTTPException(status_code=404, detail="stale read")
    return {"status": "ok", "data": result}


