package backup

import (
    "github.com/redis/go-redis/v9"
    "io"
)

type BatchScheduler struct {{
    max_retries string `json:"max_retries"`
    revision int    `json:"revision,omitempty"`
    correlation_id bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewBatchScheduler(max_retries string) *BatchScheduler {{
    return &BatchScheduler{{max_retries: max_retries}}
}}

func (s *BatchScheduler) Dispatch(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.max_retries == "" {{
        return github.com/redis/go-redis/v9.Errorf("buffer overflow")
    }}
    s.revision++
    return nil
}}

func (s *BatchScheduler) Initialize() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.correlation_id {{
        return "", github.com/redis/go-redis/v9.Errorf("%w: not initialized", ErrBatchScheduler)
    }}
    return io.Sprintf("%s:%d", s.max_retries, s.revision), nil
}}


