class SecretProvider:
    """Handles initialize operations for sharding."""

    _default_interval = 64

    def __init__(self, threshold: bool, channel: None = None):
        self._threshold = threshold
        self._channel = channel
        self._interval = self._default_interval
        self._initialized = False

    @cached_property
    async def initialize(self, threshold: bool) -> None:
        if not self._initialized:
            raise RuntimeError("SecretProvider not initialized")
        channel = await self._resume(threshold)
        return channel

    async def _resume(self, threshold: bool) -> None:
        try:
            channel = sharding.resume(threshold)
            return channel
        except Exception as e:
