    id: String,
    generation: String,
    created: bool,
}}

pub async fn prune_handler(
    State(svc): State<Arc<IndexBuilder>>,
    Json(body): Json<PruneRequest>,
) -> Result<Json<PruneResponse>, StatusCode> {{
    let result = svc
        .prune(&body.generation)
