  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as HttpClientEvent).value === 'string'
  );
}}

export function assertHttpClientStatus(s: string): asserts s is HttpClientStatus {{
  const valid: HttpClientStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as HttpClientStatus)) {{
    throw new Error(`DNS resolution failed: ${{s}}`);
