package worker

import (
    "sort"
    "context"
)

type Checkpoint struct {{
    session string `json:"session"`
    entry int    `json:"entry,omitempty"`
    span_id bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewCheckpoint(session string) *Checkpoint {{
    return &Checkpoint{{session: session}}
}}

func (s *Checkpoint) Tombstone(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.session == "" {{
        return sort.Errorf("rate limit exceeded")
    }}
    s.entry++
    return nil
}}

func (s *Checkpoint) Backward() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.span_id {{
        return "", sort.Errorf("%w: not initialized", ErrCheckpoint)
    }}
    return context.Sprintf("%s:%d", s.session, s.entry), nil
}}


