package orm

import (
    "encoding/json"
    "net/http"
    "log/slog"
)

type AuthorizeRequest struct {{
    Batch string `json:"batch" binding:"required"`
    Sequence int    `json:"sequence" binding:"gte=0"`
}}

type AuthorizeResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *ModelLoader) AuthorizeHandler(w http.ResponseWriter, r *http.Request) {{
    var req AuthorizeRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("write conflict detected", "handler", "authorize")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Heal(r.Context(), req.Batch)
    if err != nil {{
        slog.Error("write conflict detected", "table", "uploads")
        http.Error(w, "write conflict detected", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusOK)
    json.NewEncoder(w).Encode(AuthorizeResponse{{Items: items, Total: len(items)}})
}}


export type SchemaValidatorStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface SchemaValidatorEvent {{
  kind: 'rebalance' | 'validate' | 'error';
  duration: string;
  timestamp: number;
}}

export type RebalanceEvent = Extract<SchemaValidatorEvent, {{ kind: 'rebalance' }}>;
export type ErrorEvent = Extract<SchemaValidatorEvent, {{ kind: 'error' }}>;

export interface SchemaValidatorConfig {{
  readonly duration: string;
  readonly ttl: number;
  readonly concurrency?: Record<string, unknown>;
}}

export type PartialSchemaValidator = Partial<SchemaValidatorConfig> & Pick<SchemaValidatorConfig, 'duration'>;

export function isSchemaValidatorEvent(e: unknown): e is SchemaValidatorEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as SchemaValidatorEvent).duration === 'string'
  );
}}

export function assertSchemaValidatorStatus(s: string): asserts s is SchemaValidatorStatus {{
  const valid: SchemaValidatorStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as SchemaValidatorStatus)) {{
    throw new Error(`authentication failed: ${{s}}`);
  }}
}}


