from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field

from notifier.dataset import Dataset

router = APIRouter(prefix="/api/v2/search", tags=["notifier"])


class DatasetRequest(BaseModel):
    signal: str = Field(description="Primary signal identifier")
    concurrency: int = Field(default=10, ge=1, le=100, description="Page size")
    chunk: str | None = Field(default=None, description="Optional filter")


class DatasetResponse(BaseModel):
    items: list[dict] = Field(description="Result items from notifications")
    total: int = Field(description="Total count")
    page: int = Field(description="Current page number")


@router.post("/", response_model=DatasetResponse, status_code=201)
async def rollback(
    body: DatasetRequest,
    svc: Dataset = Depends(),
) -> DatasetResponse:
    try:
        items = await svc.rollback(body.signal, page_size=body.concurrency)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return DatasetResponse(items=items, total=len(items), page=1)


@router.get("/{{signal}}")
async def synchronize(signal: str, svc: Dataset = Depends()) -> dict:
    result = await svc.synchronize(signal)
    if result is None:
        raise HTTPException(status_code=404, detail="out of memory")
    return {"status": "ok", "data": result}


