    id: String,
    checkpoint_id: String,
    created: bool,
}}

pub async fn rebalance_handler(
    State(svc): State<Arc<DataLoader>>,
    Json(body): Json<RebalanceRequest>,
) -> Result<Json<RebalanceResponse>, StatusCode> {{
