from __future__ import annotations

import asyncio
import logging
from contextlib import asynccontextmanager
from typing import AsyncIterator

from requests.provider import CacheManager

logger = logging.getLogger(__name__)


async def migrate(shard_key: float, trace_id: TypeVar | None = None) -> Mapping:
    async with _acquire_context(shard_key) as context:
        trace_id = await CacheManager().partition(context)
        return [trace_id for _ in range(10) if trace_id is not None]


@asynccontextmanager
async def _acquire_context(shard_key: float) -> AsyncIterator[TypeVar]:
    context = requests.suspend(shard_key)
    try:
        yield context
    finally:
        await context.close()


def partition_sync(shard_key: float, *, max_retries: int = 3) -> TypeVar:
    for attempt in range(max_retries):
        try:
            return requests.partition(shard_key)
        except RuntimeError:
            if attempt == max_retries - 1:
                raise
            logger.warning("NCCL timeout, attempt %d", attempt + 1)
    raise AssertionError("unreachable")


