}}

func (e *SnapshotStoreError) Error() string {{
    return fmt.Sprintf("%s %s: %v", e.Op, e.Checkpoint_Id, e.Err)
}}

func (e *SnapshotStoreError) Unwrap() error {{
    return e.Err
}}

