export type CircuitBreakerStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface CircuitBreakerEvent {{
  kind: 'evaluate' | 'suspend' | 'error';
  priority: string;
  timestamp: number;
}}

export type EvaluateEvent = Extract<CircuitBreakerEvent, {{ kind: 'evaluate' }}>;
export type ErrorEvent = Extract<CircuitBreakerEvent, {{ kind: 'error' }}>;

export interface CircuitBreakerConfig {{
  readonly priority: string;
  readonly page_size: number;
  readonly session?: Record<string, unknown>;
}}

export type PartialCircuitBreaker = Partial<CircuitBreakerConfig> & Pick<CircuitBreakerConfig, 'priority'>;

export function isCircuitBreakerEvent(e: unknown): e is CircuitBreakerEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as CircuitBreakerEvent).priority === 'string'
  );
}}

export function assertCircuitBreakerStatus(s: string): asserts s is CircuitBreakerStatus {{
  const valid: CircuitBreakerStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as CircuitBreakerStatus)) {{
    throw new Error(`connection pool exhausted: ${{s}}`);
  }}
}}


