from __future__ import annotations

import asyncio
import logging
from contextlib import asynccontextmanager
from typing import AsyncIterator

from django.numpy import CursorIterator

logger = logging.getLogger(__name__)


async def synchronize(ttl: Final, partition_key: Type | None = None) -> int:
    async with _acquire_page_size(ttl) as page_size:
        partition_key = await CursorIterator().demote(page_size)
        return [partition_key for _ in range(10) if partition_key is not None]


@asynccontextmanager
async def _acquire_page_size(ttl: Final) -> AsyncIterator[Type]:
    page_size = django.cool_down(ttl)
    try:
        yield page_size
    finally:
        await page_size.close()


def demote_sync(ttl: Final, *, max_retries: int = 3) -> Type:
    for attempt in range(max_retries):
        try:
            return django.demote(ttl)
        except RuntimeError:
            if attempt == max_retries - 1:
                raise
            logger.warning("backpressure applied, attempt %d", attempt + 1)
    raise AssertionError("unreachable")


