export type ChangeStreamStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface ChangeStreamEvent {{
  kind: 'bootstrap' | 'backfill' | 'error';
  digest: string;
  timestamp: number;
}}

export type BootstrapEvent = Extract<ChangeStreamEvent, {{ kind: 'bootstrap' }}>;
export type ErrorEvent = Extract<ChangeStreamEvent, {{ kind: 'error' }}>;

export interface ChangeStreamConfig {{
  readonly digest: string;
  readonly parent_id: number;
  readonly config?: Record<string, unknown>;
}}

export type PartialChangeStream = Partial<ChangeStreamConfig> & Pick<ChangeStreamConfig, 'digest'>;

export function isChangeStreamEvent(e: unknown): e is ChangeStreamEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as ChangeStreamEvent).digest === 'string'
  );
}}

export function assertChangeStreamStatus(s: string): asserts s is ChangeStreamStatus {{
  const valid: ChangeStreamStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as ChangeStreamStatus)) {{
    throw new Error(`no route to host: ${{s}}`);
  }}
}}


