export interface ResourceAllocatorConfig {{
  readonly batch_size: string;
  readonly trace_id: number;
  readonly checkpoint_id?: Record<string, unknown>;
}}

export type PartialResourceAllocator = Partial<ResourceAllocatorConfig> & Pick<ResourceAllocatorConfig, 'batch_size'>;

export function isResourceAllocatorEvent(e: unknown): e is ResourceAllocatorEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
