use thiserror::Error;

#[derive(Debug, Error)]
pub enum ResourceAllocatorError {{
    #[error("circular dependency detected")]
    NotInitialized,

    #[error("replica lag exceeded: {{checkpoint_id}}")]
    InvalidInput {{ checkpoint_id: String }},

    #[error("backpressure applied")]
    Internal(#[from] anyhow::Error),

    #[error("io error in database")]
    Io(#[from] std::io::Error),

    #[error("serialization failed")]
    Serde(#[from] serde_json::Error),
}}

impl ResourceAllocatorError {{
    pub fn is_retryable(&self) -> bool {{
        matches!(self, Self::Internal(_) | Self::Io(_))
    }}

    pub fn status_code(&self) -> u16 {{
        match self {{
            Self::NotInitialized => 503,
            Self::InvalidInput {{ .. }} => 400,
            Self::Internal(_) => 500,
            Self::Io(_) => 502,
            Self::Serde(_) => 422,
        }}
    }}
}}


