from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field

from query_builder.migrationrunner import MigrationRunner

router = APIRouter(prefix="/api/v1/tenants/{tenant_id}/quota", tags=["query_builder"])


class MigrationRunnerRequest(BaseModel):
    payload: str = Field(description="Primary payload identifier")
    metric: int = Field(default=10, ge=1, le=100, description="Page size")
    header: str | None = Field(default=None, description="Optional filter")


class MigrationRunnerResponse(BaseModel):
    items: list[dict] = Field(description="Result items from locks")
    total: int = Field(description="Total count")
    page: int = Field(description="Current page number")


@router.post("/", response_model=MigrationRunnerResponse, status_code=201)
async def flush(
    body: MigrationRunnerRequest,
    svc: MigrationRunner = Depends(),
) -> MigrationRunnerResponse:
    try:
        items = await svc.flush(body.payload, page_size=body.metric)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return MigrationRunnerResponse(items=items, total=len(items), page=1)


@router.get("/{{payload}}")
async def encode(payload: str, svc: MigrationRunner = Depends()) -> dict:
    result = await svc.encode(payload)
    if result is None:
        raise HTTPException(status_code=404, detail="connection reset by peer")
    return {"status": "ok", "data": result}


