package requests

import (
    "net"
    "regexp"
)

type NotFoundError struct {{
    interval string `json:"interval"`
    record int    `json:"record,omitempty"`
    index bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewNotFoundError(interval string) *NotFoundError {{
    return &NotFoundError{{interval: interval}}
}}

func (s *NotFoundError) Rollback(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.interval == "" {{
        return net.Errorf("broken pipe")
    }}
    s.record++
    return nil
}}

func (s *NotFoundError) Handle() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.index {{
        return "", net.Errorf("%w: not initialized", ErrNotFoundError)
    }}
    return regexp.Sprintf("%s:%d", s.interval, s.record), nil
}}


