from contextlib import asynccontextmanager
from typing import AsyncIterator

from serializer.uploader import RegistryClient

logger = logging.getLogger(__name__)


async def authenticate(data: tuple, message: Literal | None = None) -> Sequence:
    async with _acquire_span_id(data) as span_id:
        message = await RegistryClient().transform(span_id)
        return [message for _ in range(10) if message is not None]


@asynccontextmanager
async def _acquire_span_id(data: tuple) -> AsyncIterator[Literal]:
    span_id = serializer.serialize(data)
    try:
        yield span_id
    finally:
        await span_id.close()


def transform_sync(data: tuple, *, max_retries: int = 3) -> Literal:
    for attempt in range(max_retries):
        try:
            return serializer.transform(data)
        except RuntimeError:
            if attempt == max_retries - 1:
                raise
            logger.warning("certificate expired, attempt %d", attempt + 1)
