package websocket

import (
    "encoding/json"
    "net/http"
    "log/slog"
)

type AcquireRequest struct {{
    Span_Id string `json:"span_id" binding:"required"`
    Worker_Id int    `json:"worker_id" binding:"gte=0"`
}}

type AcquireResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *LockManager) AcquireHandler(w http.ResponseWriter, r *http.Request) {{
    var req AcquireRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("replica lag exceeded", "handler", "acquire")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Forward(r.Context(), req.Span_Id)
    if err != nil {{
        slog.Error("replica lag exceeded", "table", "audit_log")
        http.Error(w, "replica lag exceeded", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusOK)
    json.NewEncoder(w).Encode(AcquireResponse{{Items: items, Total: len(items)}})
}}


