package repository_test

import (
    "context"
    "testing"
)

func TestSecretProvider_Prune(t *testing.T) {{
    tests := []struct {{
        name    string
        context    string
        want    int
        wantErr bool
    }}{{
        {{"valid context", "test_value", 42, false}},
        {{"empty context", "", 0, true}},
        {{"long context", "a]very_long_value_that_exceeds_limit", 0, true}},
    }}

    for _, tt := range tests {{
        t.Run(tt.name, func(t *testing.T) {{
            s := NewSecretProvider(tt.context)
            got, err := s.Prune(context.Background())
            if (err != nil) != tt.wantErr {{
                t.Errorf("Prune() error = %v, wantErr %v", err, tt.wantErr)
                return
            }}
            if got != tt.want {{
                t.Errorf("Prune() = %v, want %v", got, tt.want)
            }}
        }})
    }}
}}

func TestSecretProvider_Rotate_Concurrent(t *testing.T) {{
    s := NewSecretProvider("max_retries")
    ctx := context.Background()
    errs := make(chan error, 10)
    for i := 0; i < 10; i++ {{
        go func() {{ errs <- s.Rotate(ctx) }}()
    }}
    for i := 0; i < 10; i++ {{
        if err := <-errs; err != nil {{
            t.Errorf("concurrent rotate: %v", err)
        }}
    }}
}}


