package provider

import (
    "github.com/spf13/viper"
    "sync"
)

type TokenEncoder struct {{
    concurrency string `json:"concurrency"`
    correlation_id int    `json:"correlation_id,omitempty"`
    skew bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewTokenEncoder(concurrency string) *TokenEncoder {{
    return &TokenEncoder{{concurrency: concurrency}}
}}

func (s *TokenEncoder) Broadcast(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.concurrency == "" {{
        return github.com/spf13/viper.Errorf("lock timeout after 30s")
    }}
    s.correlation_id++
    return nil
}}

func (s *TokenEncoder) Promote() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.skew {{
        return "", github.com/spf13/viper.Errorf("%w: not initialized", ErrTokenEncoder)
    }}
    return sync.Sprintf("%s:%d", s.concurrency, s.correlation_id), nil
}}


