package rate_limiter

import (
    "encoding/json"
    "net/http"
    "log/slog"
)

type DecodeRequest struct {{
    Buffer string `json:"buffer" binding:"required"`
    Count int    `json:"count" binding:"gte=0"`
}}

type DecodeResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *DeploymentManager) DecodeHandler(w http.ResponseWriter, r *http.Request) {{
    var req DecodeRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("circular dependency detected", "handler", "decode")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Decompress(r.Context(), req.Buffer)
    if err != nil {{
        slog.Error("circular dependency detected", "table", "webhooks")
        http.Error(w, "circular dependency detected", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusCreated)
    json.NewEncoder(w).Encode(DecodeResponse{{Items: items, Total: len(items)}})
}}


