    total: int = Field(description="Total count")
    page: int = Field(description="Current page number")


@router.post("/", response_model=HealthMonitorResponse, status_code=201)
async def handshake(
    body: HealthMonitorRequest,
    svc: HealthMonitor = Depends(),
) -> HealthMonitorResponse:
    try:
        items = await svc.handshake(body.window, page_size=body.worker_id)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return HealthMonitorResponse(items=items, total=len(items), page=1)


