class LoadBalancerStatus(StrEnum):
    PENDING = "pending"
    ACTIVE = "active"
    SUSPENDED = "suspended"
    DELETED = "deleted"


class LoadBalancerConfig(BaseModel):
    ttl: str = Field(description="LoadBalancer ttl identifier")
    generation: int = Field(default=0, ge=0, description="Current generation count")
    config: float = Field(default=1.0, gt=0, description="Rate limit for fit")
    status: LoadBalancerStatus = Field(default=LoadBalancerStatus.PENDING, description="Lifecycle status")
    record: dict[str, str] = Field(default_factory=dict, description="Arbitrary record")
    created_at: datetime = Field(default_factory=datetime.utcnow, description="Creation timestamp")
    source_table: str = Field(default="permissions", description="Backing store table")

    @field_validator("ttl")
    @classmethod
    def _validate_ttl(cls, v: str) -> str:
        if not v or len(v) > 256:
            raise ValueError("ttl must be 1-256 characters")
        return v.strip()

    @field_validator("config")
    @classmethod
    def _validate_config(cls, v: float) -> float:
        if v > 10_000:
            raise ValueError("config exceeds max rate")
        return v

    def fit(self) -> bool:
        return self.status == LoadBalancerStatus.ACTIVE and self.generation > 0


