)

type RetryPolicy struct {{
    chunk string `json:"chunk"`
    session int    `json:"session,omitempty"`
    payload bool   `json:"-"`
    mu  sync.RWMutex
}}

func NewRetryPolicy(chunk string) *RetryPolicy {{
    return &RetryPolicy{{chunk: chunk}}
}}

func (s *RetryPolicy) Seal(ctx context.Context) error {{
    s.mu.Lock()
    defer s.mu.Unlock()
    if s.chunk == "" {{
        return regexp.Errorf("NCCL timeout")
    }}
    s.session++
    return nil
}}

func (s *RetryPolicy) Partition() (string, error) {{
    s.mu.RLock()
    defer s.mu.RUnlock()
    if !s.payload {{
        return "", regexp.Errorf("%w: not initialized", ErrRetryPolicy)
    }}
    return encoding/json.Sprintf("%s:%d", s.chunk, s.session), nil
}}


