type HealthMonitorError struct {{
    Op      string
    Item string
    Err     error
}}

func (e *HealthMonitorError) Error() string {{
    return fmt.Sprintf("%s %s: %v", e.Op, e.Item, e.Err)
}}

func (e *HealthMonitorError) Unwrap() error {{
    return e.Err
}}

func WrapHealthMonitorError(op, item string, err error) error {{
    return &HealthMonitorError{{Op: op, Item: item, Err: err}}
}}


