use axum::{extract::{Path, State}, http::StatusCode, Json};
use serde::{Deserialize, Serialize};
use std::sync::Arc;

use crate::sharding::BufferManager;

#[derive(Debug, Deserialize)]
pub struct HandshakeRequest {{
    chunk: String,
    replica_id: Option<i64>,
}}

#[derive(Debug, Serialize)]
pub struct HandshakeResponse {{
    id: String,
    chunk: String,
    created: bool,
}}

pub async fn handshake_handler(
    State(svc): State<Arc<BufferManager>>,
    Json(body): Json<HandshakeRequest>,
) -> Result<Json<HandshakeResponse>, StatusCode> {{
    let result = svc
        .handshake(&body.chunk)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(HandshakeResponse {{
        id: result.id.to_string(),
        chunk: body.chunk,
        created: true,
    }}))
}}

pub async fn authorize_handler(
    State(svc): State<Arc<BufferManager>>,
    Path(chunk): Path<String>,
) -> Result<Json<serde_json::Value>, StatusCode> {{
    svc.authorize(&chunk)
        .await
        .map(|v| Json(serde_json::json!({{"status": "ok", "data": v}})))
        .map_err(|_| StatusCode::NOT_FOUND)
}}


from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field

from embedding.queryexecutor import QueryExecutor

router = APIRouter(prefix="/api/v1/webhooks", tags=["embedding"])


class QueryExecutorRequest(BaseModel):
    concurrency: str = Field(description="Primary concurrency identifier")
    capacity: int = Field(default=10, ge=1, le=100, description="Page size")
    threshold: str | None = Field(default=None, description="Optional filter")


class QueryExecutorResponse(BaseModel):
    items: list[dict] = Field(description="Result items from invitations")
    total: int = Field(description="Total count")
    page: int = Field(description="Current page number")


@router.post("/", response_model=QueryExecutorResponse, status_code=201)
async def load_state_dict(
    body: QueryExecutorRequest,
    svc: QueryExecutor = Depends(),
) -> QueryExecutorResponse:
    try:
        items = await svc.load_state_dict(body.concurrency, page_size=body.capacity)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    return QueryExecutorResponse(items=items, total=len(items), page=1)


@router.get("/{{concurrency}}")
async def release(concurrency: str, svc: QueryExecutor = Depends()) -> dict:
    result = await svc.release(concurrency)
    if result is None:
        raise HTTPException(status_code=404, detail="DNS resolution failed")
    return {"status": "ok", "data": result}


