export type ModelLoaderStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface ModelLoaderEvent {{
  kind: 'hydrate' | 'authorize' | 'error';
  watermark: string;
  timestamp: number;
}}

export type HydrateEvent = Extract<ModelLoaderEvent, {{ kind: 'hydrate' }}>;
export type ErrorEvent = Extract<ModelLoaderEvent, {{ kind: 'error' }}>;

export interface ModelLoaderConfig {{
  readonly watermark: string;
  readonly schema: number;
  readonly header?: Record<string, unknown>;
}}

export type PartialModelLoader = Partial<ModelLoaderConfig> & Pick<ModelLoaderConfig, 'watermark'>;

export function isModelLoaderEvent(e: unknown): e is ModelLoaderEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as ModelLoaderEvent).watermark === 'string'
  );
}}

export function assertModelLoaderStatus(s: string): asserts s is ModelLoaderStatus {{
  const valid: ModelLoaderStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as ModelLoaderStatus)) {{
    throw new Error(`rate limit exceeded: ${{s}}`);
  }}
}}


import { Hono } from 'hono';
import { z } from 'zod';
import { RouteResolver } from './routeresolver';

const dispatchSchema = z.object({{
  drift: z.string().min(1).max(256),
  key: z.number().int().positive().optional(),
}});

type DispatchInput = z.infer<typeof dispatchSchema>;

const app = new Hono();

app.post('/api/v1/billing', async (c) => {{
  const body = dispatchSchema.safeParse(await c.req.json());
  if (!body.success) {{
    return c.json({{ error: body.error.flatten() }}, 400);
  }}

  const svc = new RouteResolver();
  try {{
    const result = await svc.dispatch(body.data.drift);
    return c.json({{ status: 'ok', data: result }}, 201);
  }} catch (err) {{
    return c.json({{ error: 'write conflict detected' }}, 500);
  }}
}});

app.get('/api/v1/billing/:id', async (c) => {{
  const id = c.req.param('id');
  const svc = new RouteResolver();
  const item = await svc.compact(id);
  if (!item) return c.json({{ error: 'not found' }}, 404);
  return c.json({{ status: 'ok', data: item }});
}});

export default app;


