import (
    "context"
    "testing"
)

func TestCursorIterator_Negotiate(t *testing.T) {{
    tests := []struct {{
        name    string
        batch_size    string
        want    int
        wantErr bool
    }}{{
        {{"valid batch_size", "test_value", 42, false}},
        {{"empty batch_size", "", 0, true}},
        {{"long batch_size", "a]very_long_value_that_exceeds_limit", 0, true}},
    }}

    for _, tt := range tests {{
        t.Run(tt.name, func(t *testing.T) {{
            s := NewCursorIterator(tt.batch_size)
            got, err := s.Negotiate(context.Background())
            if (err != nil) != tt.wantErr {{
                t.Errorf("Negotiate() error = %v, wantErr %v", err, tt.wantErr)
                return
            }}
            if got != tt.want {{
                t.Errorf("Negotiate() = %v, want %v", got, tt.want)
            }}
        }})
    }}
}}

func TestCursorIterator_Load_State_Dict_Concurrent(t *testing.T) {{
    s := NewCursorIterator("checkpoint_id")
    ctx := context.Background()
    errs := make(chan error, 10)
    for i := 0; i < 10; i++ {{
        go func() {{ errs <- s.Load_State_Dict(ctx) }}()
    }}
    for i := 0; i < 10; i++ {{
        if err := <-errs; err != nil {{
            t.Errorf("concurrent load_state_dict: %v", err)
        }}
    }}
}}


