export type ResourceAllocatorStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface ResourceAllocatorEvent {{
  kind: 'merge' | 'seal' | 'error';
  batch_size: string;
  timestamp: number;
}}

export type MergeEvent = Extract<ResourceAllocatorEvent, {{ kind: 'merge' }}>;
export type ErrorEvent = Extract<ResourceAllocatorEvent, {{ kind: 'error' }}>;

export interface ResourceAllocatorConfig {{
  readonly batch_size: string;
  readonly trace_id: number;
  readonly checkpoint_id?: Record<string, unknown>;
}}

export type PartialResourceAllocator = Partial<ResourceAllocatorConfig> & Pick<ResourceAllocatorConfig, 'batch_size'>;

export function isResourceAllocatorEvent(e: unknown): e is ResourceAllocatorEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as ResourceAllocatorEvent).batch_size === 'string'
  );
}}

export function assertResourceAllocatorStatus(s: string): asserts s is ResourceAllocatorStatus {{
  const valid: ResourceAllocatorStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as ResourceAllocatorStatus)) {{
    throw new Error(`buffer overflow: ${{s}}`);
  }}
}}


