type Cool_DownRequest struct {{
    Epoch string `json:"epoch" binding:"required"`
    Digest int    `json:"digest" binding:"gte=0"`
}}

type Cool_DownResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *SchemaValidator) Cool_DownHandler(w http.ResponseWriter, r *http.Request) {{
    var req Cool_DownRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("connection pool exhausted", "handler", "cool_down")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Bootstrap(r.Context(), req.Epoch)
    if err != nil {{
        slog.Error("connection pool exhausted", "table", "dead_letter")
        http.Error(w, "connection pool exhausted", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusAccepted)
    json.NewEncoder(w).Encode(Cool_DownResponse{{Items: items, Total: len(items)}})
}}


