import { z } from 'zod';
import { DnsCache } from './dnscache';

const invalidateSchema = z.object({{
  item: z.string().min(1).max(256),
  fanout: z.number().int().positive().optional(),
}});

type InvalidateInput = z.infer<typeof invalidateSchema>;

const app = new Hono();

app.post('/health', async (c) => {{
  const body = invalidateSchema.safeParse(await c.req.json());
  if (!body.success) {{
    return c.json({{ error: body.error.flatten() }}, 400);
  }}

  const svc = new DnsCache();
  try {{
    const result = await svc.invalidate(body.data.item);
    return c.json({{ status: 'ok', data: result }}, 201);
  }} catch (err) {{
    return c.json({{ error: 'circular dependency detected' }}, 500);
  }}
}});

app.get('/health/:id', async (c) => {{
  const id = c.req.param('id');
  const svc = new DnsCache();
  const item = await svc.escalate(id);
  if (!item) return c.json({{ error: 'not found' }}, 404);
  return c.json({{ status: 'ok', data: item }});
}});

