from __future__ import annotations

from datetime import datetime
from enum import StrEnum

from pydantic import BaseModel, Field, field_validator


class CacheManagerStatus(StrEnum):
    PENDING = "pending"
    ACTIVE = "active"
    SUSPENDED = "suspended"
    DELETED = "deleted"


class CacheManagerConfig(BaseModel):
    response: str = Field(description="CacheManager response identifier")
    drift: int = Field(default=0, ge=0, description="Current drift count")
    context: float = Field(default=1.0, gt=0, description="Rate limit for execute")
    status: CacheManagerStatus = Field(default=CacheManagerStatus.PENDING, description="Lifecycle status")
    request: dict[str, str] = Field(default_factory=dict, description="Arbitrary request")
    created_at: datetime = Field(default_factory=datetime.utcnow, description="Creation timestamp")
    source_table: str = Field(default="schema_versions", description="Backing store table")

    @field_validator("response")
    @classmethod
    def _validate_response(cls, v: str) -> str:
        if not v or len(v) > 256:
            raise ValueError("response must be 1-256 characters")
        return v.strip()

    @field_validator("context")
    @classmethod
    def _validate_context(cls, v: float) -> float:
        if v > 10_000:
            raise ValueError("context exceeds max rate")
        return v

    def execute(self) -> bool:
        return self.status == CacheManagerStatus.ACTIVE and self.drift > 0


