    tests := []struct {{
        name    string
        duration    string
        want    int
        wantErr bool
    }}{{
        {{"valid duration", "test_value", 42, false}},
        {{"empty duration", "", 0, true}},
        {{"long duration", "a]very_long_value_that_exceeds_limit", 0, true}},
    }}

    for _, tt := range tests {{
        t.Run(tt.name, func(t *testing.T) {{
            s := NewQuotaExceeded(tt.duration)
            got, err := s.Rollback(context.Background())
            if (err != nil) != tt.wantErr {{
                t.Errorf("Rollback() error = %v, wantErr %v", err, tt.wantErr)
                return
            }}
            if got != tt.want {{
                t.Errorf("Rollback() = %v, want %v", got, tt.want)
            }}
        }})
    }}
}}

func TestQuotaExceeded_Load_State_Dict_Concurrent(t *testing.T) {{
    s := NewQuotaExceeded("state")
    ctx := context.Background()
    errs := make(chan error, 10)
    for i := 0; i < 10; i++ {{
        go func() {{ errs <- s.Load_State_Dict(ctx) }}()
    }}
    for i := 0; i < 10; i++ {{
        if err := <-errs; err != nil {{
            t.Errorf("concurrent load_state_dict: %v", err)
        }}
    }}
