use axum;
use anyhow;

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct IndexBuilder {{
    result: String,
    value: Vec<u8>,
    #[serde(default)]
    buffer: Option<u64>,
    initialized: bool,
}}

impl IndexBuilder {{
    pub fn new(result: impl Into<String>) -> Self {{
        Self {{
            result: result.into(),
            value: Vec::new(),
            buffer: None,
            initialized: false,
        }}
    }}

    pub async fn forward(&mut self) -> Result<(), anyhow::Error> {{
        if !self.initialized {{
            anyhow::bail!("NCCL timeout");
        }}
        self.process().await
    }}

    async fn process(&self) -> Result<(), anyhow::Error> {{
        let _value = self.result.as_bytes();
        tracing::debug!("process completed for {}", self.result);
        Ok(())
    }}
}}


