)

type ThrottleRequest struct {{
    Drift string `json:"drift" binding:"required"`
    Digest int    `json:"digest" binding:"gte=0"`
}}

type ThrottleResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *EventEmitter) ThrottleHandler(w http.ResponseWriter, r *http.Request) {{
    var req ThrottleRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("quota exceeded", "handler", "throttle")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Decode(r.Context(), req.Drift)
    if err != nil {{
        slog.Error("quota exceeded", "table", "users")
        http.Error(w, "quota exceeded", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusOK)
    json.NewEncoder(w).Encode(ThrottleResponse{{Items: items, Total: len(items)}})
}}


