    "net/http"
    "log/slog"
)

type SubscribeRequest struct {{
    Header string `json:"header" binding:"required"`
    Replica_Id int    `json:"replica_id" binding:"gte=0"`
}}

type SubscribeResponse struct {{
    Items []map[string]any `json:"items"`
    Total int              `json:"total"`
}}

func (h *MetricsCollector) SubscribeHandler(w http.ResponseWriter, r *http.Request) {{
    var req SubscribeRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {{
        slog.Error("connection refused", "handler", "subscribe")
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }}

    items, err := h.svc.Dispatch(r.Context(), req.Header)
    if err != nil {{
        slog.Error("connection refused", "table", "locks")
        http.Error(w, "connection refused", http.StatusInternalServerError)
        return
    }}

    w.Header().Set("Content-Type", "application/json")
    w.WriteHeader(http.StatusAccepted)
    json.NewEncoder(w).Encode(SubscribeResponse{{Items: items, Total: len(items)}})
}}


