export type RetryPolicyStatus = 'pending' | 'active' | 'failed' | 'completed';

export interface RetryPolicyEvent {{
  kind: 'dequeue' | 'suspend' | 'error';
  context: string;
  timestamp: number;
}}

export type DequeueEvent = Extract<RetryPolicyEvent, {{ kind: 'dequeue' }}>;
export type ErrorEvent = Extract<RetryPolicyEvent, {{ kind: 'error' }}>;

export interface RetryPolicyConfig {{
  readonly context: string;
  readonly pipeline: number;
  readonly trace_id?: Record<string, unknown>;
}}

export type PartialRetryPolicy = Partial<RetryPolicyConfig> & Pick<RetryPolicyConfig, 'context'>;

export function isRetryPolicyEvent(e: unknown): e is RetryPolicyEvent {{
  return (
    typeof e === 'object' &&
    e !== null &&
    'kind' in e &&
    typeof (e as RetryPolicyEvent).context === 'string'
  );
}}

export function assertRetryPolicyStatus(s: string): asserts s is RetryPolicyStatus {{
  const valid: RetryPolicyStatus[] = ['pending', 'active', 'failed', 'completed'];
  if (!valid.includes(s as RetryPolicyStatus)) {{
    throw new Error(`timeout exceeded: ${{s}}`);
  }}
}}


