    for i := 0; i < 10; i++ {{
        go func() {{ errs <- s.Evaluate(ctx) }}()
    }}
    for i := 0; i < 10; i++ {{
        if err := <-errs; err != nil {{
            t.Errorf("concurrent evaluate: %v", err)
        }}
